const $=s=>document.querySelector(s);const agents=[{name:'Intake agent',role:'Organizes incoming documents',icon:'↓',work:'Ingesting 3 documents',x:21,y:22},{name:'Invoice agent',role:'Validates invoices against POs',icon:'▤',work:'Matching invoice #1042',x:21,y:147},{name:'Reconciliation',role:'Matches transactions and ledgers',icon:'⇄',work:'Reconciling 8 transactions',x:21,y:272},{name:'Orchestrator',role:'Coordinates your finance team',icon:'✳',work:'Routing 24 active cases',x:45,y:147},{name:'Risk agent',role:'Detects anomalies and exposure',icon:'◈',work:'Assessing vendor risk',x:70,y:22},{name:'Approval agent',role:'Enforces policy and approvals',icon:'✓',work:'Reviewing 2 exceptions',x:70,y:147},{name:'Treasury agent',role:'Plans and executes payments',icon:'▥',work:'Scheduling payment run',x:70,y:272},{name:'Reporting agent',role:'Closes the loop with clear records',icon:'▧',work:'Updating daily ledger',x:45,y:272}];
const cases=[{id:'1042',title:'Vendor invoice reconciliation',entity:'Linear Technologies · INV-2026-089',amount:'$12,450.00',state:'Resolved',duration:'1m 42s',count:5,type:'invoice'},{id:'1041',title:'Unusual expense detected',entity:'Mercury · Transaction #8921',amount:'$3,280.00',state:'Needs review',duration:'4m 12s',count:4,type:'risk'},{id:'1040',title:'International vendor payment',entity:'Figma Inc. · Payment #721',amount:'$8,600.00',state:'In progress',duration:'38s',count:4,type:'payment'},{id:'1039',title:'Month-end balance verification',entity:'NetSuite · October close',amount:'$48,920.00',state:'Resolved',duration:'2m 08s',count:4,type:'close'}];let currentCase=cases[0],zoom=1,filter='All cases',query='',view='overview',paused=false;
const edge=(x,y,a,b)=>`<path class="edge liveedge" d="M ${x} ${y} C ${(x+a)/2} ${y}, ${(x+a)/2} ${b}, ${a} ${b}"/>`;
$('#network-inner').innerHTML=`<svg viewBox="0 0 800 370" preserveAspectRatio="none">${edge(100,110,168,70)+edge(100,242,168,195)+edge(100,242,168,320)+edge(315,70,360,195)+edge(315,195,360,195)+edge(315,320,360,195)+edge(507,195,560,70)+edge(507,195,560,195)+edge(507,195,560,320)+edge(507,195,433,320)+edge(634,273,507,320)}</svg><div class="a2alabel" style="left:64%;top:105px">A2A ⇄</div><div class="a2alabel" style="left:41%;top:104px">A2A ⇄</div><button class="node source" style="left:2%;top:77px" data-source="Connected banks"><div class="node-top">▥ &nbsp;Bank feeds</div><small>Mercury · Chase</small></button><button class="node source" style="left:2%;top:213px" data-source="Documents & ERP"><div class="node-top">▤ &nbsp;Documents</div><small>NetSuite · Email</small></button>${agents.map((a,i)=>`<button class="node ${i===3?'hub':''}" style="left:${a.x}%;top:${a.y}px;width:18.4%" data-agent="${i}"><div class="node-top"><span class="node-icon">${a.icon}</span>${a.name}</div><small>${i===3?'TEAM COORDINATOR':'FINANCE AGENT'}</small><div class="node-status"><span><i class="dot"></i>${i===5?'2 in review':'Active'}</span><span>↗</span></div></button>`).join('')}`;
const activity=[['⇄','Invoice → Reconciliation','Invoice matched to purchase order.','Just now'],['✓','Case #1042 resolved','Payment approved. Ledger updated.','12 seconds ago'],['◈','Risk → Approval','Anomaly flagged for human review.','34 seconds ago'],['↓','Intake received 3 documents','Extracted and routed to invoice agent.','1 minute ago']];$('#activity').innerHTML=activity.map(a=>`<div class="event"><div class="event-icon">${a[0]}</div><div><strong>${a[1]}</strong><p>${a[2]}</p><time>${a[3]}</time></div></div>`).join('');
function renderCases(){const rows=cases.filter(c=>(filter==='All cases'||c.state===filter)&&(c.title+' '+c.entity+' '+c.id).toLowerCase().includes(query.toLowerCase()));$('#case-panel').innerHTML=`<div class="panelhead"><span>Case explorer <small>Follow the work from start to finish</small></span><div class="case-toolbar"><div class="tabs">${['All cases','Needs review','Resolved'].map(f=>`<button class="${f===filter?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><input class="search" aria-label="Search cases" placeholder="⌕  Search cases..." value="${query.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}"></div></div><table><thead><tr><th>CASE / WORKFLOW</th><th>STATUS</th><th>AMOUNT</th><th>AGENTS</th><th>DURATION</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr class="case-row" tabindex="0" role="button" aria-label="Open case ${c.id}" data-case="${c.id}"><td><span class="caseid">#${c.id} &nbsp;</span><strong>${c.title}</strong><small style="margin-left:43px">${c.entity}</small></td><td><span class="status ${c.state==='Needs review'?'review':c.state==='In progress'?'progress':''}">${c.state==='Resolved'?'✓':'◌'} ${c.state}</span></td><td>${c.amount}</td><td><div class="miniavatars">${['IN','RC','AP'].map(s=>`<span>${s}</span>`).join('')}<span>+${c.count-3}</span></div></td><td style="color:#89957f">${c.duration}</td><td style="color:#859a70">↗</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No cases match your search.</div>':''}<div class="tablebottom"><span>${rows.length} recent cases · 24 in workspace</span><span>Click a case to explore its trace ↗</span></div>`;$('.search').oninput=e=>{const p=e.target.selectionStart;query=e.target.value;renderCases();$('.search').focus();$('.search').setSelectionRange(p,p)}}renderCases();
function navigate(v){view=v;$('#overview').classList.toggle('hidden',!['overview','cases'].includes(v));$('#trace').classList.add('hidden');$('#directory').classList.toggle('hidden',!['agents','sources'].includes(v));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadcrumb').textContent=({overview:'Overview',cases:'Case explorer',agents:'Agents',sources:'Data sources'})[v];if(v==='cases'){$('#case-panel').scrollIntoView({behavior:'smooth',block:'start'});$('.search').focus()}else{window.scrollTo(0,0)}if(v==='agents'||v==='sources')directory(v);}
const tracks={invoice:[{agent:0,title:'Invoice received',desc:'Invoice INV-2026-089 arrived from the vendor inbox. Extracted vendor, amount, currency, and purchase order reference.',payload:'Document: INV-2026-089.pdf<br>Vendor: Linear Technologies<br>Amount: $12,450.00 USD',time:'09:41:00',tag:'SOURCE INGESTED',hash:'a81f2c',x:5,y:27},{agent:1,title:'Invoice validated',desc:'Verified invoice fields, vendor identity, and duplicate checks. Sent the normalized invoice to Reconciliation.',payload:'Duplicate check: passed<br>Vendor identity: verified<br>Purchase order: PO-0847',time:'09:41:14',tag:'A2A HANDOFF',hash:'b39d8e',x:5,y:161},{agent:2,title:'Three-way match passed',desc:'Matched the invoice with its purchase order and goods receipt. All line items reconcile with zero variance.',payload:'Purchase order: PO-0847<br>Goods receipt: GR-212<br>Variance: $0.00',time:'09:41:37',tag:'VERIFIED',hash:'c52a19',x:39,y:161},{agent:5,title:'Policy approval granted',desc:'Confirmed the invoice falls within the vendor payment policy and available budget. Authorized Treasury to schedule payment.',payload:'Policy: AP standard v2.4<br>Budget check: passed<br>Approval: automatic',time:'09:42:01',tag:'POLICY CHECK',hash:'d67b40',x:73,y:161},{agent:6,title:'Payment scheduled',desc:'Scheduled payment for the next business day and wrote the reconciliation record to the ledger. Case resolved.',payload:'Payment: PAY-2026-721<br>Ledger record: JE-4821<br>Outcome: resolved',time:'09:42:42',tag:'CASE RESOLVED',hash:'e90c72',x:73,y:328}],risk:[{agent:0,title:'Transaction received',desc:'Bank feed delivered a new card transaction for review.',payload:'Source: Mercury<br>Transaction: #8921<br>Amount: $3,280.00',time:'09:37:00',tag:'SOURCE INGESTED'},{agent:2,title:'Expense categorized',desc:'Categorized the transaction as software services and compared the merchant with prior spend.',payload:'Category: software services<br>Merchant: Cloud Atlas<br>Prior average: $240.00',time:'09:37:18',tag:'A2A HANDOFF'},{agent:4,title:'Spend anomaly detected',desc:'The charge is above the established baseline. Risk requested approval before continuing.',payload:'Deviation: 13.7× baseline<br>Risk level: elevated<br>Reason: first-time merchant',time:'09:37:44',tag:'EXCEPTION'},{agent:5,title:'Human review requested',desc:'The case is paused for a finance lead to validate the charge. No further payment action has been taken.',payload:'Reviewer: Jamie Lee<br>Status: awaiting review<br>Next: confirm supporting receipt',time:'09:38:01',tag:'AWAITING REVIEW'}],payment:[{agent:0,title:'Payment request received',desc:'Received a payment request from the vendor portal.',payload:'Vendor: Figma Inc.<br>Amount: $8,600.00<br>Currency: USD',time:'09:43:00',tag:'SOURCE INGESTED'},{agent:4,title:'Beneficiary verified',desc:'Verified the beneficiary and checked vendor risk signals.',payload:'Beneficiary: verified<br>Risk level: low<br>Sanctions screening: clear',time:'09:43:09',tag:'VERIFIED'},{agent:5,title:'Payment approved',desc:'Checked the request against payment policy and spending limits.',payload:'Policy: international payments<br>Limit check: passed<br>Approval: automatic',time:'09:43:21',tag:'POLICY CHECK'},{agent:6,title:'Preparing transfer',desc:'Treasury is preparing a transfer instruction. The case remains in progress.',payload:'Rail: international wire<br>Status: preparing<br>Execution: pending',time:'09:43:38',tag:'IN PROGRESS'}],close:[{agent:0,title:'Ledger snapshot received',desc:'Received the October balance snapshot from NetSuite.',payload:'Source: NetSuite<br>Period: October 2026<br>Balance: $48,920.00',time:'09:32:00',tag:'SOURCE INGESTED'},{agent:2,title:'Balances reconciled',desc:'Compared bank and general ledger balances. No unexplained differences remain.',payload:'Bank balance: $48,920.00<br>Ledger balance: $48,920.00<br>Difference: $0.00',time:'09:32:40',tag:'VERIFIED'},{agent:5,title:'Close checks approved',desc:'Confirmed required reconciliations and supporting evidence are complete.',payload:'Checks: 12 / 12 passed<br>Exceptions: 0<br>Approval: automatic',time:'09:33:25',tag:'POLICY CHECK'},{agent:7,title:'Close report generated',desc:'Generated the balance verification report and attached the audit record. Case resolved.',payload:'Report: OCT-BAL-2026<br>Evidence: 12 records<br>Outcome: resolved',time:'09:34:08',tag:'CASE RESOLVED'}]};
function stepsFor(c){return tracks[c.type].map((s,i)=>({...s,hash:s.hash||['f23a71','a74c02','b98e16','d71f09'][i],x:s.x??[5,39,73,73][i],y:s.y??[35,35,35,230][i]}))}
function openCase(id){currentCase=cases.find(c=>c.id===id);if(!currentCase)return;$('#overview').classList.add('hidden');$('#directory').classList.add('hidden');$('#trace').classList.remove('hidden');$('#breadcrumb').textContent=`Case explorer / #${id}`;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='cases'));window.scrollTo(0,0);const c=currentCase,steps=stepsFor(c);$('#trace').innerHTML=`<div class="trace-intro"><button class="action back" id="back" aria-label="Back to overview">←</button><span class="caseid">CASE #${c.id}</span><span style="color:#a5ae9b">/</span><span>Execution trace</span><span class="status ${c.state==='Needs review'?'review':c.state==='In progress'?'progress':''}" style="margin-left:auto">${c.state}</span></div><h1>${c.title}</h1><p>${c.entity} · A complete history of this case, from intake to outcome.</p><div class="trace-meta"><span><b>${steps.length} agents</b> involved</span><span><b>${steps.length-1} A2A</b> handoffs</span><span><b>${c.duration}</b> elapsed</span><span><b>${c.amount}</b> case value</span></div><div class="trace-layout"><section class="panel"><div class="panelhead"><span>Case graph <small>Only the work that belongs to #${c.id}</small></span><button class="chip" id="replay">▷ Replay trace</button></div><div class="trace-graph"><div class="trace-canvas"><svg viewBox="0 0 800 500" preserveAspectRatio="none">${steps.slice(1).map((s,i)=>{const p=steps[i];const same=p.x===s.x;return `<path class="edge" d="M ${p.x*8+95} ${p.y+82} ${same?'L '+(s.x*8+95)+' '+s.y:'C '+(p.x*8+95)+' '+(p.y+125)+', '+(s.x*8+95)+' '+(s.y-30)+', '+(s.x*8+95)+' '+s.y}"/>`}).join('')}</svg>${steps.map((s,i)=>`<button class="trace-step ${i===0?'active':''}" style="left:${s.x}%;top:${s.y}px;width:25%" data-step="${i}"><span class="commit"><span class="stepnum">${i+1}</span>${s.hash} · ${s.time}</span><strong>${agents[s.agent].icon} &nbsp;${agents[s.agent].name}</strong><small>${s.title}</small></button>`).join('')}</div></div><div class="tablebottom"><span>● Source → handoffs → ${c.state==='Resolved'?'resolution':'current state'}</span><span>Select a step to inspect →</span></div></section><section class="panel" id="step-detail"></section></div>`;selectStep(0);$('#back').onclick=()=>navigate('overview');$('#replay').onclick=replay;}
function selectStep(i){const steps=stepsFor(currentCase),s=steps[i];document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===i));$('#step-detail').innerHTML=`<div class="panelhead">Step details <span class="chip">${i+1} / ${steps.length}</span></div><div class="detail"><span class="status ${s.tag==='AWAITING REVIEW'?'review':''}">${s.tag}</span><h2>${s.title}</h2><p>${s.desc}</p><div class="detail-label">EVIDENCE & OUTPUT</div><div class="payload">${s.payload}</div><div class="detail-label">EXECUTION</div><div class="detail-pair"><span>Agent</span><b>${agents[s.agent].name}</b></div><div class="detail-pair"><span>Timestamp</span><b>${s.time}</b></div><div class="detail-pair"><span>Trace ID</span><b>${s.hash}</b></div><div class="detail-pair"><span>Handoff</span><b>${i?agents[steps[i-1].agent].name+' →':'Source →'} ${agents[s.agent].name}</b></div><button class="action" id="next-step" style="margin-top:20px;width:100%;justify-content:center">${i===steps.length-1?'↺ Back to first step':'Next handoff →'}</button></div>`;$('#next-step').onclick=()=>selectStep((i+1)%steps.length);}
let replayTimer;function replay(){clearInterval(replayTimer);let i=0;selectStep(0);$('#replay').textContent='◌ Replaying…';replayTimer=setInterval(()=>{if($('#trace').classList.contains('hidden')){clearInterval(replayTimer);return}i++;if(i>=stepsFor(currentCase).length){clearInterval(replayTimer);$('#replay').textContent='▷ Replay trace';return}selectStep(i)},1300)}
function drawer(title,sub,body){$('#drawer').innerHTML=`<div class="drawer-content"><button class="drawer-close" aria-label="Close details">×</button><span class="section-label" style="padding:0">${sub}</span><h2>${title}</h2>${body}</div>`;$('#drawer').classList.remove('hidden');$('.drawer-close').onclick=()=>$('#drawer').classList.add('hidden');$('.drawer-close').focus()}
function agentDetails(i){const a=agents[i];drawer(a.name,'FINANCE TEAM / AGENT',`<span class="status">● Online</span><p style="margin-top:20px">${a.role}. ${a.work}.</p><div class="detail-label">ACTIVITY</div><div class="payload">Protocol: A2A<br>Health: operational<br>Current task: ${a.work}<br>Last heartbeat: 2 seconds ago</div><div class="detail-label">RELATED CASES</div>${cases.filter(c=>stepsFor(c).some(s=>s.agent===i)).map(c=>`<button class="action" data-case="${c.id}" style="width:100%;margin:5px 0;justify-content:space-between">#${c.id} ${c.title}<span>↗</span></button>`).join('')||'<p>Coordinating across the workspace.</p>'}`)}
function sourceDetails(name){drawer(name,'CONNECTED SOURCE',`<span class="status">● Connected</span><p style="margin-top:20px">Demo data flows into the Intake agent, then gets routed to the right specialist.</p><div class="detail-label">CONNECTION HEALTH</div><div class="payload">Sync status: up to date<br>Last sync: 24 Oct 2026, 09:43<br>Destination: Intake agent<br>Mode: sample data</div>`)}
function directory(v){const sources=[['Mercury','Bank transactions & balances','Banking'],['Chase','Bank transactions & balances','Banking'],['NetSuite','Invoices, purchase orders & ledger','ERP'],['Vendor inbox','Invoices & supporting documents','Email']];$('#directory').innerHTML=`<div class="heading"><div><h1>${v==='agents'?'A team built to work together.':'Your data, connected.'}</h1><p>${v==='agents'?'Eight specialists. One coordinated finance operation.':'The source of every case, document, and decision.'}</p></div><span class="status">${v==='agents'?'8 agents online':'4 sources connected'}</span></div><div class="agent-list">${v==='agents'?agents.map((a,i)=>`<button class="panel agent-card" data-agent="${i}"><span class="node-icon">${a.icon}</span><h3>${a.name}</h3><p>${a.role}</p><div class="detail-label"><span class="dot"></span>ONLINE <span style="float:right">Inspect agent ↗</span></div></button>`).join(''):sources.map(s=>`<button class="panel agent-card" data-source="${s[0]}"><span class="chip">${s[2]}</span><h3>${s[0]}</h3><p>${s[1]}</p><div class="detail-label"><span class="dot"></span>CONNECTED <span style="float:right">View source ↗</span></div></button>`).join('')}</div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-case]');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.agent!==undefined)agentDetails(Number(b.dataset.agent));if(b.dataset.source)sourceDetails(b.dataset.source);if(b.dataset.case){$('#drawer').classList.add('hidden');openCase(b.dataset.case)}if(b.dataset.filter){filter=b.dataset.filter;renderCases()}if(b.dataset.step!==undefined)selectStep(Number(b.dataset.step))});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#drawer').classList.add('hidden');if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-case]')){e.preventDefault();openCase(e.target.dataset.case)}});$('#drawer').onclick=e=>{if(e.target===$('#drawer'))$('#drawer').classList.add('hidden')};$('#pause').onclick=()=>{paused=!paused;$('#network').classList.toggle('paused',paused);$('#pause').innerHTML=paused?'▷ <span>Resume live view</span>':'Ⅱ <span>Pause live view</span>';$('.live').innerHTML=paused?'Ⅱ Paused':'<span class="dot"></span>Live'};function setZoom(z){zoom=Math.min(1.4,Math.max(.6,z));$('#network-inner').style.transform=`scale(${zoom})`}$('#zoomin').onclick=()=>setZoom(zoom+.1);$('#zoomout').onclick=()=>setZoom(zoom-.1);$('#fit').onclick=()=>setZoom(1);$('#activity-all').onclick=()=>drawer('Activity stream','WORKSPACE / LIVE ACTIVITY',activity.concat([['✓','Treasury confirmed payment','Payment run #720 completed.','2 minutes ago']]).map(a=>`<div class="event"><span class="event-icon">${a[0]}</span><div><strong>${a[1]}</strong><p>${a[2]}</p><time>${a[3]}</time></div></div>`).join(''));setInterval(()=>{if(!paused){const n=Number($('#messages').textContent.replace(',',''));$('#messages').textContent=(n+1).toLocaleString('en-US')}},8000);
